                            <img proton-src='${imageURL}'/>
                        </div>`;

        const message: MessageState = {
            localID: 'messageWithRemote',
            data: {
                ID: 'messageID',
                Sender: {
                    Name: 'normal address',
                    Address: 'normal@proton.me',
